def D(id, parts, aliases, served_in="handheld", tags=("street_food",), **kw):
    if kw.get("alias_side"):
        kw.setdefault("alias_side_locale", "de-AT")
    return dict(id=id, countries=["AT"], category="street_food", part_refs=parts, served_in=served_in, tags=list(tags), aliases=aliases, **kw)


